/**
 * cityData — Static fallback city database for Equinox Nexus
 *
 * Used when the backend simulation API is unavailable or when the user
 * requests a city that isn't in the backend's Numbeo training set.
 *
 * SOURCE: Curated from Numbeo, OECD, and IMF regional datasets.
 * UPDATE POLICY: Backend simulation results always override these values.
 *                Update this file when new research data is available.
 *
 * Fields:
 *   wealthMultiplier1 — Expected wealth multiple vs salary after 1 year
 *   wealthMultiplier5 — Expected wealth multiple vs salary after 5 years
 *   riskScore         — Relocation risk (0 = safest, 1 = riskiest)
 *   qualityScore      — Quality of life score (0–1 scale)
 *   costIncrease      — Cost of living increase vs global average (%)
 *   taxBurden         — Effective tax rate (%)
 *   hiddenCosts       — Estimated annual hidden relocation costs (USD)
 *   riskLevel         — 'Low' | 'Medium' | 'High'
 */

export type CityMetrics = {
  wealthMultiplier1: number;
  wealthMultiplier5: number;
  riskScore: number;
  qualityScore: number;
  costIncrease: number;
  taxBurden: number;
  hiddenCosts: number;
  riskLevel: string;
};

