/**
 * Find the best matching cityData key for a user-entered city name.
 * Priority: exact match → city-part match → partial match → returns input.
 */
export function findCityKey(cityName: string): string {
  const normalizedInput = cityName.toLowerCase().trim();

  // Exact match
  for (const key of Object.keys(cityData)) {
    if (key.toLowerCase() === normalizedInput) return key;
  }
  // City part match (e.g. "Paris" matches "Paris, France")
  for (const key of Object.keys(cityData)) {
    const cityPart = key.toLowerCase().split(',')[0].trim();
    if (cityPart === normalizedInput) return key;
  }
  // Partial match
  for (const key of Object.keys(cityData)) {
    const cityPart = key.toLowerCase().split(',')[0];
    if (key.toLowerCase().includes(normalizedInput) || normalizedInput.includes(cityPart)) return key;
  }

  return cityName;
}

/**
 * Build a scenario object from cityData, used as fallback when backend is unavailable.
 */
export function buildFallbackScenario(cityKey: string, salary: number) {
  const data = cityData[cityKey] ?? DEFAULT_CITY_METRICS;
  return {
    location: cityKey,
    year_1_wealth: salary * data.wealthMultiplier1,
    year_5_wealth: salary * data.wealthMultiplier5,
    risk_score: data.riskScore,
    quality_score: data.qualityScore,
    cost_increase: data.costIncrease,
    tax_burden: data.taxBurden,
    hidden_costs: data.hiddenCosts,
    risk_level: data.riskLevel,
  };
}
